def generate_vocab_dataset():
    all_vocab = []
    word_id = 1
    for u in UNITS_DATA:
        u_num = u["unit"]
        u_title = u["unit_title"]
        u_cat = u["category"]
        for w in u["words"]:
            w["id"] = word_id
            w["unit"] = u_num
            w["unit_title"] = u_title
            w["category"] = u_cat
            if "status" not in w:
                w["status"] = "new"
            all_vocab.append(w)
            word_id += 1

    output_path = 'backend/data/hacknao_vocab.json'
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(all_vocab, f, ensure_ascii=False, indent=2)

    print(f"Đã xuất thành công {len(all_vocab)} từ vựng chuẩn Unit 1 đến Unit 10 vào: {output_path}")

if __name__ == '__main__':
    generate_vocab_dataset()
